"""系统管理路由 — /api/system/*"""

from __future__ import annotations

import asyncio

from fastapi import APIRouter
from pydantic import BaseModel

from autowsgr.image_resources import get_manifest_report
from autowsgr.infra.config import ConfigPathNotFoundError
from autowsgr.infra.logger import get_logger
from autowsgr.server.device_lease import (
    DeviceOperationBusyError,
    device_operation_lease,
)
from autowsgr.server.errors import ErrorCode, api_error
from autowsgr.server.schemas import ApiResponse
from autowsgr.server.task_manager import task_manager

from .. import main as _main


_log = get_logger('server')

router = APIRouter(prefix='/api/system', tags=['system'])
_TASK_STOP_TIMEOUT_SECONDS = 30.0


class SystemStartRequest(BaseModel):
    """系统启动请求。"""

    config_path: str | None = None


@router.post('/start', response_model=ApiResponse)
async def system_start(request: SystemStartRequest) -> ApiResponse:
    """启动系统 (连接模拟器、启动游戏)。"""
    # 5.4：启动/停止过渡中直接 503，绝不排队抢 lifecycle_lock。
    busy = _main.lifecycle_busy_error()
    if busy is not None:
        raise busy

    # 先声明 starting，再等待锁：并发的 start/stop 与 task_start 会立刻
    # 看到过渡态并 503，而不是陪启动一起等几分钟。
    _main.set_system_state(_main.SystemState.STARTING)
    lease_token = None
    try:
        try:
            lease_token = device_operation_lease.acquire('api:system-start')
        except DeviceOperationBusyError as error:
            raise api_error(
                409,
                ErrorCode.DEVICE_BUSY,
                str(error),
                headers={'Retry-After': '1'},
            ) from error

        async with _main.lifecycle_lock:
            if _main._ctx is not None:
                if await _main.is_emulator_alive():
                    return ApiResponse(success=True, message='系统已启动')
                # 5.1：模拟器关掉后 _ctx 仍非空。若直接返回「已启动」，用户点
                # 启动会得到假成功、界面在「空闲/未连接」之间来回跳；先回收
                # 半死上下文再重新连接。任务运行中时上面的设备租约已经 409。
                _log.warning('[System] 检测到残留上下文但模拟器已断开，先回收再重启')
                await _main.release_context()

            try:
                from autowsgr.scheduler import launch

                # 6.5：只有「未指定路径」才允许默认探测 usersettings.yaml；
                # 显式路径原样下传，由 ConfigManager 做 fail fast。
                config_path = request.config_path or None
                _log.info(
                    '[System] 正在启动, 配置: {}',
                    config_path or '自动检测 usersettings.yaml / 内置默认',
                )
                _main._ctx = await asyncio.to_thread(launch, config_path=config_path)
                # 5.9：核心上下文不认识 FastAPI，这里注入掉落事件桥。
                _main.bind_context_observers(_main._ctx)
                _log.info('[System] 启动成功')

                return ApiResponse(success=True, message='系统启动成功')

            except ConfigPathNotFoundError as e:
                # 6.5：显式路径拼错 → 400 + 稳定错误码，不再静默用默认配置。
                _log.error('[System] 配置路径不存在: {}', e.path)
                raise api_error(
                    400,
                    ErrorCode.CONFIG_PATH_NOT_FOUND,
                    f'配置文件不存在: {e.path}；请检查配置路径，'
                    '未指定路径时才使用内置默认配置',
                    data={'config_path': str(e.path)},
                ) from e

            except Exception as e:
                _log.error('[System] 启动失败: {}', e)
                raise api_error(
                    500,
                    ErrorCode.SYSTEM_START_FAILED,
                    str(e),
                ) from e
    finally:
        if lease_token is not None:
            device_operation_lease.release(lease_token)
        # 成功 → ready；失败/取消 → 回到未启动。租约释放也在这之后，
        # 避免「状态已 ready、设备租约还没还」的 409 缝隙。
        _main.set_system_state(
            _main.SystemState.READY
            if _main._ctx is not None
            else _main.SystemState.IDLE
        )


@router.post('/stop', response_model=ApiResponse)
async def system_stop() -> ApiResponse:
    """停止系统。"""
    # 5.4：过渡中直接 503（启动中的系统不可被停止请求插队）。
    busy = _main.lifecycle_busy_error()
    if busy is not None:
        raise busy

    _main.set_system_state(_main.SystemState.STOPPING)
    try:
        async with _main.lifecycle_lock:
            if _main._ctx is None:
                return ApiResponse(success=True, message='系统未运行')

            if task_manager.is_running:
                task_manager.stop_task()

            completed = await asyncio.to_thread(
                task_manager.wait_for_completion,
                _TASK_STOP_TIMEOUT_SECONDS,
            )
            if not completed:
                # 5.3：协作式停止已超时。先摘掉上下文并强制断开设备，
                # 否则 UI 报失败、后台线程还在点屏幕（R09 的原始病灶）。
                _log.error(
                    '[System] 任务未在 {}s 内停止，强制断开设备并清理上下文',
                    _TASK_STOP_TIMEOUT_SECONDS,
                )
                disconnect_ok = await _main.force_release_context()
                error = (
                    f'停止超时（{_TASK_STOP_TIMEOUT_SECONDS:g} 秒），'
                    '已强制断开设备连接并清理系统上下文，请重新启动系统'
                )
                if not disconnect_ok:
                    error += '（设备断开调用未在限时内返回）'
                raise api_error(
                    500,
                    ErrorCode.SYSTEM_STOP_TIMEOUT,
                    error,
                    data={
                        'forced_disconnect': True,
                        'context_cleared': _main._ctx is None,
                    },
                )

            try:
                lease_token = device_operation_lease.acquire('api:system-stop')
            except DeviceOperationBusyError as error:
                raise api_error(
                    409,
                    ErrorCode.DEVICE_BUSY,
                    str(error),
                    headers={'Retry-After': '1'},
                ) from error
            try:
                # 先断开设备（停解码线程、关 socket、清理设备端 scrcpy-server），
                # 再释放全局上下文；否则反复启停会在模拟器里累积连接与进程。
                await _main.release_context()
                _log.info('[System] 系统已停止')
                return ApiResponse(success=True, message='系统已停止')
            finally:
                device_operation_lease.release(lease_token)
    finally:
        _main.set_system_state(_main.SystemState.IDLE)


@router.get('/status', response_model=ApiResponse)
async def system_status() -> ApiResponse:
    """获取系统状态。"""
    from autowsgr.ui.page import get_recognizer_errors

    manifest = get_manifest_report()
    ctx = _main._ctx
    resolution_fallback = bool(
        getattr(getattr(ctx, 'ctrl', None), 'resolution_fallback', False)
    )
    # 5.1：真实探活。设备已断开时既不能报 connected，也不能报
    # game_running —— 否则界面会显示一片绿色但实际什么都点不动。
    emulator_connected = await _main.is_emulator_alive()
    return ApiResponse(
        success=True,
        data={
            'system_state': _main.get_system_state().value,
            'status': task_manager.current_task.status.value
            if task_manager.current_task
            else 'idle',
            'emulator_connected': emulator_connected,
            'game_running': emulator_connected,
            'resolution_fallback': resolution_fallback,
            'recognizer_errors': get_recognizer_errors(),
            'current_task': task_manager.current_task.task_id
            if task_manager.current_task
            else None,
            'device_lease': task_manager.get_device_lease(),
            'manifest_ok': bool(manifest['ok']),
            'manifest_errors': list(manifest['errors']),
        },
    )


@router.get('/emulator/devices', response_model=ApiResponse)
async def emulator_devices() -> ApiResponse:
    """查询 ADB 设备列表，用于检查模拟器运行状态。

    会先对已知 TCP serial（MuMu 等）执行 adb connect，再列出设备。
    """
    try:
        from autowsgr.emulator.detector import connect_and_list_devices

        devices = await asyncio.to_thread(connect_and_list_devices)
        return ApiResponse(
            success=True,
            data=[{'serial': s, 'status': st} for s, st in devices],
        )
    except Exception as e:
        _log.warning('[System] ADB 设备查询失败: {}', e)
        raise api_error(
            502,
            ErrorCode.EMULATOR_QUERY_FAILED,
            str(e),
        ) from e
